package vn.cinema.service;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.JdbcTemplate;import vn.cinema.repository.NotificationRepository;import vn.cinema.entity.Notification;import vn.cinema.exception.Problem;import java.util.*;
@Service public class NotificationService{private final NotificationRepository repo;private final JdbcTemplate db;public NotificationService(NotificationRepository r,JdbcTemplate d){repo=r;db=d;}@Transactional public Notification send(long bookingId,long userId,String title,String message){db.update("INSERT IGNORE INTO notification(booking_id,user_id,title,message,read_status,created_at,updated_at) VALUES (?,?,?,?,false,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",bookingId,userId,title,message);return repo.findByBookingId(bookingId).orElseThrow();}public List<Notification> list(long userId,boolean admin){return admin?repo.findAll():repo.findByUserIdOrderByCreatedAtDesc(userId);}@Transactional public Notification read(long id,long userId,boolean admin){var n=repo.findById(id).orElseThrow(Problem::missing);if(!admin&&!n.userId.equals(userId))throw new Problem(403,"Không có quyền đọc thông báo này");n.readStatus=true;return n;}}